// Package storage keeps onboarding assets on local disk (SALES_UPLOAD_DIR,
// default ./.uploads/sales). Keys are generated by the app; anything that
// would escape the root is refused.
package storage

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"
)

var ErrInvalidKey = errors.New("kunci file tidak valid")

type Local struct{ Root string }

func NewLocal(root string) *Local {
	if root == "" {
		root = ".uploads/sales"
	}
	return &Local{Root: root}
}

func (l *Local) path(key string) (string, error) {
	if key == "" || strings.Contains(key, "..") || strings.HasPrefix(key, "/") {
		return "", ErrInvalidKey
	}
	root, err := filepath.Abs(l.Root)
	if err != nil {
		return "", err
	}
	abs := filepath.Join(root, filepath.FromSlash(key))
	if !strings.HasPrefix(abs, root+string(filepath.Separator)) {
		return "", ErrInvalidKey
	}
	return abs, nil
}

func (l *Local) Put(_ context.Context, key string, data []byte) error {
	abs, err := l.path(key)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return err
	}
	return os.WriteFile(abs, data, 0o644)
}

func (l *Local) Get(_ context.Context, key string) ([]byte, error) {
	abs, err := l.path(key)
	if err != nil {
		return nil, err
	}
	return os.ReadFile(abs)
}
